/**
 * POST /api/compare
 *
 * Fan-out comparison across three model lanes. Every answer is generated by a
 * REAL model call at request time, then checked by the firewall (microservice
 * when available, otherwise the real in-process LLM/NLI detector).
 *
 * SSE events stream progress stage by stage so the UI can show live pipeline
 * activity: started -> generated -> checking -> result -> complete.
 */

import { after, NextResponse } from "next/server";
import { logCheckRun } from "@/lib/telemetry";
import { createGenerationUsageProof } from "@/lib/telemetry/usage-proof";
import { generateBlackboxAnswer } from "@/lib/llm";
import {
  activeDetector,
  extractEntities,
  isPromptEcho,
  retrievalFacts,
  runFirewallCheck,
  serviceReachable,
  toFactDetails,
  type FactDetail,
} from "@/lib/firewall";

const INTERPRETABILITY_URL = process.env.INTERPRETABILITY_SERVICE_URL ?? "";
const BLACKBOX_URL = process.env.BLACKBOX_SERVICE_URL ?? "";
const INTERNAL_API_KEY = process.env.INTERNAL_API_KEY ?? "";

const VALID_MODELS = ["local-gemma", "chatgpt", "claude", "groq", "openrouter"];
const DEFAULT_MODELS = ["local-gemma", "groq", "openrouter"];
const REQUEST_TIMEOUT_MS = 30_000;

type Verdict = "trustworthy" | "uncertain" | "needs_correction";

interface ModelStage {
  name: string;
  status: "completed" | "skipped" | "unavailable";
  latency_ms?: number;
  details?: Record<string, unknown>;
}

interface ModelResult {
  model: string;
  provider: string | null;
  model_name: string | null;
  answer: string | null;
  verdict: Verdict | null;
  confidence: number | null;
  evidence: string[];
  evidenceItems: Array<{ kind: string; statement: string; detail: string; supports: boolean }>;
  signalList: Array<{ label: string; value?: number; detail: string; risk?: boolean }>;
  corrected_answer: string | null;
  used_facts: string[];
  used_fact_details: FactDetail[];
  retrieved_facts: string[];
  reference_facts: string[];
  reference_fact_details: FactDetail[];
  entities: string[];
  signals: Record<string, unknown>;
  latency_ms: number;
  stages: ModelStage[];
  retrieval_error: string | null;
  verification_status: "pending" | "complete" | "error";
  mode: "microservice" | "inprocess" | "unavailable";
  error?: string;
}

interface Agreement {
  available: boolean;
  method: "nli" | "lexical" | "unavailable";
  all_agree: boolean;
  majority_answer_cluster: string;
  outliers: string[];
  score: number | null;
}

function serviceHeaders() {
  const headers: Record<string, string> = { "Content-Type": "application/json" };
  if (INTERNAL_API_KEY) headers["X-Internal-Api-Key"] = INTERNAL_API_KEY;
  return headers;
}

async function fetchWithTimeout(url: string, init: RequestInit, timeoutMs: number): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

// ── Generation ────────────────────────────────────────────────────────────────

interface Generated {
  answer: string;
  provider: string;
  model: string;
  latency_ms: number;
  usage_proof: unknown;
  mode: "microservice" | "inprocess";
}

async function generateFor(model: string, question: string): Promise<Generated> {
  const started = Date.now();

  if (model === "local-gemma" && INTERPRETABILITY_URL && await serviceReachable(INTERPRETABILITY_URL)) {
    const res = await fetchWithTimeout(`${INTERPRETABILITY_URL.replace(/\/$/, "")}/generate`, {
      method: "POST",
      headers: serviceHeaders(),
      body: JSON.stringify({ question }),
    }, 20_000);
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data?.detail?.message ?? data?.detail ?? "Gemma generation failed.");
    if (typeof data.answer !== "string" || !data.answer.trim()) throw new Error("Gemma returned an empty answer.");
    return {
      answer: data.answer,
      provider: data.provider ?? "Google",
      model: data.model ?? "Gemma-2-2B-it",
      latency_ms: Date.now() - started,
      usage_proof: null,
      mode: "microservice",
    };
  }

  const result = await generateBlackboxAnswer(question, { temperature: 0.2, maxTokens: 300, noCache: true });
  return {
    answer: result.text,
    provider: result.provider,
    model: result.model,
    latency_ms: Date.now() - started,
    usage_proof: createGenerationUsageProof({
      model_name: result.model,
      input_tokens: null,
      output_tokens: null,
      cached_input_tokens: null,
    }, question, result.text),
    mode: "inprocess",
  };
}

function errorResult(model: string, error: string, latencyMs: number): ModelResult {
  return {
    model,
    provider: null,
    model_name: null,
    answer: null,
    verdict: null,
    confidence: null,
    evidence: [],
    evidenceItems: [],
    signalList: [],
    corrected_answer: null,
    used_facts: [],
    used_fact_details: [],
    retrieved_facts: [],
    reference_facts: [],
    reference_fact_details: [],
    entities: [],
    signals: {},
    latency_ms: latencyMs,
    stages: [{ name: "generation", status: "unavailable", latency_ms: latencyMs, details: { error } }],
    retrieval_error: null,
    verification_status: "error",
    mode: "unavailable",
    error,
  };
}

// ── Verification ──────────────────────────────────────────────────────────────

async function verifyGenerated(
  generated: Generated,
  question: string,
  model: string
): Promise<ModelResult> {
  const started = Date.now();
  const detectorMode = await activeDetector(model);

  try {
    if (detectorMode === "inprocess") {
      const result = await runFirewallCheck({
        question,
        answer: generated.answer,
        source: model,
      });
      return {
        model,
        provider: generated.provider,
        model_name: generated.model,
        answer: generated.answer,
        verdict: result.verdict,
        confidence: result.confidence,
        evidence: result.evidence,
        evidenceItems: result.evidenceItems,
        signalList: result.signalList,
        corrected_answer: result.corrected_answer,
        used_facts: result.used_facts,
        used_fact_details: result.used_fact_details,
        retrieved_facts: result.referenceFacts,
        reference_facts: result.referenceFacts,
        reference_fact_details: result.reference_fact_details,
        entities: result.entities,
        signals: { ...result.signals, generation_model: generated.model },
        latency_ms: generated.latency_ms + (Date.now() - started),
        stages: [
          { name: "generation", status: "completed", latency_ms: generated.latency_ms },
          ...result.stages,
        ],
        retrieval_error: BLACKBOX_URL || !process.env.RETRIEVAL_SERVICE_URL
          ? null
          : "Knowledge service unavailable — used local reference premises.",
        verification_status: "complete",
        mode: "inprocess",
      };
    }

    // Keep original microservice detector path for deployed environments.
    const detectorUrl = model === "local-gemma" ? INTERPRETABILITY_URL : BLACKBOX_URL;
    const res = await fetchWithTimeout(`${detectorUrl.replace(/\/$/, "")}/v1/check`, {
      method: "POST",
      headers: serviceHeaders(),
      body: JSON.stringify({ text: generated.answer, source: model, question }),
    }, REQUEST_TIMEOUT_MS);
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data?.detail?.message ?? data?.detail ?? "Detector failed.");
    const facts = await retrievalFacts(question, data.entities ?? extractEntities(question, generated.answer));
    const factDetails = toFactDetails(facts);
    const evidence: string[] = Array.isArray(data.evidence)
      ? data.evidence.filter(
          (item: unknown): item is string => typeof item === "string" && !isPromptEcho(item)
        )
      : [];
    let corrected: string | null = null;
    if (facts.length && data.verdict !== "trustworthy" && process.env.RETRIEVAL_SERVICE_URL) {
      corrected = await fetch(`${process.env.RETRIEVAL_SERVICE_URL.replace(/\/$/, "")}/correct`, {
        method: "POST",
        headers: serviceHeaders(),
        body: JSON.stringify({ original_question: question, flagged_answer: generated.answer, facts }),
        signal: AbortSignal.timeout(10_000),
      }).then((r) => r.ok ? r.json().catch(() => ({})) : {}).then((d: Record<string, unknown>) =>
        typeof d.corrected_answer === "string" ? d.corrected_answer : null
      ).catch(() => null);
    }
    return {
      model,
      provider: generated.provider,
      model_name: data.model ?? generated.model,
      answer: generated.answer,
      verdict: data.verdict ?? null,
      confidence: typeof data.confidence === "number" ? data.confidence : null,
      evidence,
      evidenceItems: [],
      signalList: [],
      corrected_answer: corrected,
      used_facts: corrected ? facts : [],
      used_fact_details: corrected ? factDetails : [],
      retrieved_facts: facts,
      reference_facts: facts,
      reference_fact_details: factDetails,
      entities: data.entities ?? extractEntities(question, generated.answer),
      signals: { ...(data.signals ?? {}), generation_model: generated.model, pipeline_mode: "microservice" },
      latency_ms: generated.latency_ms + (Date.now() - started),
      stages: [
        { name: "generation", status: "completed", latency_ms: generated.latency_ms },
        { name: model === "local-gemma" ? "gemma_sae_check" : "blackbox_resampling_nli", status: "completed", latency_ms: data.latency_ms },
        { name: "retrieval", status: facts.length ? "completed" : "skipped", details: { facts_found: facts.length } },
        { name: "grounded_correction", status: corrected ? "completed" : "skipped" },
      ],
      retrieval_error: null,
      verification_status: "complete",
      mode: "microservice",
    };
  } catch (err) {
    return {
      ...errorResult(model, err instanceof Error ? err.message : "Verification failed.", Date.now() - started),
      answer: generated.answer,
      provider: generated.provider,
      model_name: generated.model,
      latency_ms: generated.latency_ms + (Date.now() - started),
      signals: { generation_model: generated.model },
    };
  }
}

// ── Agreement ─────────────────────────────────────────────────────────────────

async function computeAgreement(answers: Array<{ model: string; answer: string }>): Promise<Agreement> {
  if (answers.length < 2) {
    return {
      available: false,
      method: "unavailable",
      all_agree: false,
      majority_answer_cluster: answers[0]?.answer.slice(0, 120) ?? "",
      outliers: [],
      score: null,
    };
  }

  if (BLACKBOX_URL && await serviceReachable(BLACKBOX_URL)) {
    try {
      const res = await fetchWithTimeout(`${BLACKBOX_URL.replace(/\/$/, "")}/entail`, {
        method: "POST",
        headers: serviceHeaders(),
        body: JSON.stringify({ answers }),
      }, 10_000);
      if (res.ok) {
        const data = await res.json();
        return {
          available: true,
          method: "nli",
          all_agree: Boolean(data.all_agree),
          majority_answer_cluster: data.majority_cluster ?? answers[0].answer.slice(0, 120),
          outliers: data.outliers ?? [],
          score: typeof data.score === "number" ? data.score : null,
        };
      }
    } catch {
      // fall through to lexical
    }
  }

  const tokenize = (text: string) => new Set(
    text.toLowerCase().replace(/[^a-z0-9\s]/g, " ").split(/\s+/).filter((word) => word.length > 3)
  );
  const jaccard = (a: Set<string>, b: Set<string>) => {
    const intersection = [...a].filter((word) => b.has(word)).length;
    const union = new Set([...a, ...b]).size;
    return union ? intersection / union : 0;
  };
  const sets = answers.map((item) => tokenize(item.answer));
  let minSim = 1;
  for (let i = 0; i < sets.length; i++) {
    for (let j = i + 1; j < sets.length; j++) minSim = Math.min(minSim, jaccard(sets[i], sets[j]));
  }
  const allAgree = minSim >= 0.25;
  const averages = sets.map((set, index) => ({
    model: answers[index].model,
    score: sets.reduce((sum, other, otherIndex) =>
      otherIndex === index ? sum : sum + jaccard(set, other), 0) / (sets.length - 1),
  })).sort((a, b) => a.score - b.score);

  return {
    available: true,
    method: "lexical",
    all_agree: allAgree,
    majority_answer_cluster: answers[0].answer.slice(0, 120),
    outliers: allAgree ? [] : averages.slice(0, 1).filter((item) => item.score < 0.25).map((item) => item.model),
    score: Number(minSim.toFixed(3)),
  };
}

// ── Stream + JSON handlers ────────────────────────────────────────────────────

function streamComparison(question: string, models: string[], origin: string) {
  const encoder = new TextEncoder();
  let cancelled = false;
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      const send = (event: Record<string, unknown>) => {
        if (cancelled) return;
        try {
          controller.enqueue(encoder.encode(`data: ${JSON.stringify(event)}\n\n`));
        } catch {
          cancelled = true;
        }
      };

      void (async () => {
        const started = Date.now();
        send({ type: "started", question, models });

        // Generation for every model happens in parallel.
        const generated = await Promise.all(models.map(async (model) => {
          try {
            return { model, data: await generateFor(model, question), error: null as string | null };
          } catch (err) {
            return {
              model,
              data: null,
              error: err instanceof Error ? err.message : "Generation failed.",
            };
          }
        }));

        // Emit answers as soon as they arrive, then verify in parallel.
        const verification = generated.map(async ({ model, data, error }) => {
          if (!data) {
            const result = errorResult(model, error ?? "Generation failed.", 0);
            send({ type: "result", result });
            after(() => logCheckRun({
              source: model,
              verdict: null,
              confidence: null,
              latencyMs: 0,
              stages: result.stages,
            }));
            return result;
          }

          send({
            type: "generated",
            result: {
              model,
              provider: data.provider,
              model_name: data.model,
              answer: data.answer,
              verdict: null,
              confidence: null,
              evidence: [],
              evidenceItems: [],
              signalList: [],
              corrected_answer: null,
              used_facts: [],
              used_fact_details: [],
              retrieved_facts: [],
              reference_facts: [],
              reference_fact_details: [],
              entities: extractEntities(question, data.answer),
              signals: {},
              latency_ms: data.latency_ms,
              stages: [{ name: "generation", status: "completed", latency_ms: data.latency_ms }],
              retrieval_error: null,
              verification_status: "pending",
              mode: data.mode,
            } satisfies ModelResult,
          });
          send({ type: "checking", model });

          const result = await verifyGenerated(data, question, model);
          send({ type: "result", result });
          after(() => logCheckRun({
            source: model,
            verdict: result.verdict,
            confidence: result.confidence,
            latencyMs: result.latency_ms,
            stages: result.stages,
          }));
          return result;
        });

        const results = await Promise.all(verification);
        const agreement = await computeAgreement(
          results.filter((item) => item.answer).map((item) => ({ model: item.model, answer: item.answer as string }))
        );
        send({ type: "complete", agreement, total_latency_ms: Date.now() - started });
        if (!cancelled) controller.close();
      })().catch((err) => {
        send({ type: "error", error: err instanceof Error ? err.message : "Comparison failed." });
        if (!cancelled) controller.close();
      });
    },
    cancel() {
      cancelled = true;
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
      "X-Accel-Buffering": "no",
    },
  });
}

export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body." }, { status: 400 });
  }
  if (!body || typeof body !== "object" || !("question" in body)) {
    return NextResponse.json({ error: 'Required field: "question".' }, { status: 400 });
  }
  const { question, models = DEFAULT_MODELS } = body as { question: string; models?: string[] };
  if (typeof question !== "string" || !question.trim()) {
    return NextResponse.json({ error: "question must be a non-empty string." }, { status: 400 });
  }
  const requested = (Array.isArray(models) ? models : DEFAULT_MODELS).filter((model) => VALID_MODELS.includes(model));
  if (!requested.length) {
    return NextResponse.json({ error: "models must be a non-empty array of supported sources." }, { status: 400 });
  }

  if (request.headers.get("accept")?.includes("text/event-stream")) {
    return streamComparison(question.trim(), requested, new URL(request.url).origin);
  }

  const started = Date.now();
  const generated = await Promise.all(requested.map(async (model) => {
    try {
      return { model, data: await generateFor(model, question), error: null as string | null };
    } catch (err) {
      return { model, data: null, error: err instanceof Error ? err.message : "Generation failed." };
    }
  }));
  const results = await Promise.all(generated.map(async ({ model, data, error }) => {
    if (!data) return errorResult(model, error ?? "Generation failed.", 0);
    return verifyGenerated(data, question, model);
  }));
  const agreement = await computeAgreement(
    results.filter((item) => item.answer).map((item) => ({ model: item.model, answer: item.answer as string }))
  );
  return NextResponse.json({
    question,
    results,
    agreement,
    total_latency_ms: Date.now() - started,
  });
}
